ValidationRule.errorConditionFormula:
OR(
  AND(
    OR(
      ISPICKVAL(AF_VehicleSourceType__c, "In Stock"),
      ISPICKVAL(AF_VehicleSourceType__c, "In Transit / Ordered")
    ),
    ISBLANK(AF_Vehicle__c)
  ),
  AND(
    ISPICKVAL(AF_VehicleSourceType__c, "Pre-Order (Placeholder)"),
    ISBLANK(AF_VehicleDefinition__c)
  )
)
